const payload = $json.body ?? $json;
const event = payload.bot_event ?? payload.event;
if (event !== 'transcription.processed' || payload.transcript_status !== 'Success') return [];
if (!payload.bot_id) throw new Error('MeetStream webhook did not include bot_id.');
const contactId = payload.custom_attributes?.hubspot_contact_id;
if (!contactId) throw new Error('Set custom_attributes.hubspot_contact_id when creating the bot.');
return [{ json: { ...payload, bot_id: String(payload.bot_id), hubspot_contact_id: String(contactId) } }];

const runs = Array.isArray($json.transcriptions) ? $json.transcriptions : Array.isArray($json.data) ? $json.data : [];
const createdAt = (run) => { const time = Date.parse(run.created_at ?? ""); return Number.isFinite(time) ? time : -Infinity; };
const completed = runs.filter((run) => run?.status === 'Success' && run.transcript_id).sort((a, b) => createdAt(b) - createdAt(a));
if (!completed.length) throw new Error('No successful post-call transcription run was returned.');
return [{ json: { transcript_id: completed[0].transcript_id } }];

const segments = (Array.isArray($json.data) ? $json.data : []).map((segment) => {
  const transcript = typeof segment?.transcript === 'string' && segment.transcript.trim()
    ? segment.transcript
    : Array.isArray(segment?.words) ? segment.words.filter((word) => typeof word?.text === 'string' && word.text.trim()).map((word) => word.text.trim()).join(' ') : '';
  const speaker = segment?.speaker ?? segment?.participant?.name;
  return { transcript, speaker: typeof speaker === 'string' && speaker.trim() ? speaker : 'Speaker' };
}).filter((segment) => segment.transcript.trim());
if (!segments.length) throw new Error('MeetStream returned an empty transcript.');
const full = segments.map((segment) => `${segment.speaker ?? 'Speaker'}: ${segment.transcript ?? ''}`).join('\n');
const event = $('Accept linked sales transcript').item.json;
return [{ json: { bot_id: event.bot_id, hubspot_contact_id: event.hubspot_contact_id, transcript: full.slice(0, 60000) } }];

const text = ($json.output ?? []).filter((message) => message?.type === 'message').flatMap((message) => message.content ?? []).filter((part) => part?.type === 'output_text' && typeof part.text === 'string').map((part) => part.text).join('\n');
const raw = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
let data;
try { data = JSON.parse(raw); } catch { throw new Error('OpenAI did not return valid sales-analysis JSON.'); }
if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('OpenAI response must be a sales-analysis object.');
const value = (key) => typeof data[key] === 'string' && data[key].trim() ? data[key].trim() : 'Not stated';
const transcript = $('Prepare sales transcript').item.json.transcript;
const candidate = value('decision_makers');
let evidence = typeof data.decision_makers_evidence === 'string' ? data.decision_makers_evidence.trim() : '';
if (evidence && typeof transcript === 'string' && /^I\s+(?:am|have)\b/i.test(evidence)) {
  const prefix = candidate + ': ' + evidence;
  const turn = transcript.split(/\r?\n/).map(line => line.trim()).find(line => line.toLowerCase().startsWith(prefix.toLowerCase()));
  if (turn) evidence = turn.slice(0, prefix.length);
}
const roleSupported = candidate !== 'Not stated' && evidence && typeof transcript === 'string' && transcript.includes(evidence) && evidence.toLowerCase().includes(candidate.toLowerCase()) && /\b(?:decision[\s-]+makers?|final\s+(?:approval|say|approver))\b/i.test(evidence) && !/\b(?:no|not|never|cannot)\b|\b\w+n['’]t\b/i.test(evidence);
const botId = $('Accept linked sales transcript').item.json.bot_id;
const body = [
  `MeetStream bot: ${botId}`,
  `Summary: ${value('summary')}`,
  `Customer needs: ${value('customer_needs')}`,
  `Objections: ${value('objections')}`,
  `Budget: ${value('budget')}`,
  `Timeline: ${value('timeline')}`,
  `Decision makers: ${roleSupported ? candidate : 'Not stated'}`,
  `Decision-maker evidence: ${roleSupported ? evidence : 'Not stated'}`,
  `Competitors: ${value('competitors')}`,
  `Agreed next step: ${value('agreed_next_step')}`,
  `Deal risk: ${value('deal_risk')}`,
  '',
  'FOLLOW-UP EMAIL DRAFT — REVIEW BEFORE SENDING',
  `Subject: ${value('follow_up_subject')}`,
  value('follow_up_body')
].join('\n\n');
return [{ json: {
  hubspot_contact_id: $('Accept linked sales transcript').item.json.hubspot_contact_id,
  bot_id: botId,
  body
} }];
